import{t as e}from"./supabase.Cj3_0XfG.js";document.addEventListener(`astro:page-load`,async()=>{let t=document.getElementById(`nav-username`);if(t)try{let{data:{session:n}}=await e.auth.getSession();if(n){let{data:r}=await e.from(`profiles`).select(`username`).eq(`id`,n.user.id).single();t.textContent=r&&r.username?r.username:`Mi Perfil`}else t.textContent=`Mi Perfil`}catch(e){console.error(`Error cargando el nombre de usuario en el header:`,e)}});